                .map_err(|e| e.to_string())?;

        let new_seq = resolve_result
            .sequence_number
            .parse::<u64>()
            .unwrap_or(0);

        let cached_seq = self
            .cached_sequence_numbers
            .get(&root_ipns_name)
            .copied()
            .unwrap_or(0);

